    def _extract_image_urls(self) -> List[str]:
        """
        Extract image URLs from the current Twitter page.

        Returns:
            List of extracted image URLs
        """
        urls = set()

        # Multiple strategies to find image URLs
        strategies = [
            self._extract_from_img_elements,
            self._extract_from_tweet_containers,
            self._extract_from_media_galleries
        ]

        for strategy in strategies:
            try:
                extracted = strategy()
                urls.update(extracted)
                if len(urls) >= self.scraper_config.max_images:
                    break
                time.sleep(self.scraper_config.request_delay)
            except Exception as e:
                self.logger.warning(f"URL extraction strategy failed: {e}")
                continue

        return list(urls)[:self.scraper_config.max_images]

    def _extract_from_img_elements(self) -> List[str]:
        """Extract image URLs from img elements."""
        urls = []
        elements = self.driver.find_elements(By.TAG_NAME, 'img')

        for img in elements:
            src = img.get_attribute('src')
            if src and self._is_twitter_image_url(src):
                optimized = self._optimize_image_url(src)
                if optimized:
                    urls.append(optimized)

        return urls

    def _extract_from_tweet_containers(self) -> List[str]:
        """Extract image URLs from tweet containers."""
        urls = []
        tweets = self.driver.find_elements(By.CSS_SELECTOR, '[data-testid="tweet"]')

        for tweet in tweets:
            try:
                imgs = tweet.find_elements(By.CSS_SELECTOR, 'img[src*="pbs.twimg.com"]')
                for img in imgs:
                    src = img.get_attribute('src')
                    if src and self._is_twitter_image_url(src):
                        optimized = self._optimize_image_url(src)
                        if optimized:
                            urls.append(optimized)
            except:
                continue

        return urls

    def _extract_from_media_galleries(self) -> List[str]:
        """Extract image URLs from media galleries."""
        urls = []
        galleries = self.driver.find_elements(By.CSS_SELECTOR, '[data-testid="mediaGallery"]')

        for gallery in galleries:
            try:
                imgs = gallery.find_elements(By.TAG_NAME, 'img')
                for img in imgs:
                    src = img.get_attribute('src')
                    if src and self._is_twitter_image_url(src):
                        optimized = self._optimize_image_url(src)
                        if optimized:
                            urls.append(optimized)
            except:
                continue

        return urls

    def _download_images(self, urls: List[str], save_path: Path) -> List[str]:
        """
        Download extracted image URLs to the specified folder.

        Args:
            urls: List of image URLs to download
            save_path: Path to folder where images will be saved

        Returns:
            List of successfully downloaded image URLs
        """
        downloaded = []

        if not urls:
            self.logger.warning("No image URLs to download")
            return downloaded

        for i, url in enumerate(urls[:self.scraper_config.max_images], 1):
            try:
                # Generate unique filename
                filename = f"{self.scraper_config.target_username}_{i:03d}.jpg"
                filepath = save_path / filename

                # Ensure unique filename
                counter = 1
                while filepath.exists():
                    filename = f"{self.scraper_config.target_username}_{i:03d}_{counter}.jpg"
                    filepath = save_path / filename
                    counter += 1

                # Download with appropriate headers and timeout
                response = self.session.get(url, timeout=15)
                response.raise_for_status()

                # Verify content type
                if response.headers.get('content-type', '').startswith('image/'):
                    with open(filepath, 'wb') as f:
                        f.write(response.content)

                    # Verify file was written
                    if filepath.exists() and os.path.getsize(filepath) > 0:
                        downloaded.append(url)
                        self.downloaded_count += 1
                        self.logger.info(f"Downloaded {i}/{len(urls)}: {filename}")
                    else:
                        self.logger.warning(f"Failed to save {filename}")
                else:
                    self.logger.warning(f"Non-image content at {url}")

                # Respect rate limiting
                time.sleep(self.scraper_config.request_delay)

            except Exception as e:
                self.logger.error(f"Failed to download {url}: {e}")
                self.failed_downloads.append(url)

        return downloaded

    def _is_twitter_image_url(self, url: str) -> bool:
        """Check if URL is a Twitter image URL."""
        twitter_domains = ['pbs.twimg.com', 'twimg.com']
        return any(domain in url for domain in twitter_domains)

    def _optimize_image_url(self, url: str) -> str:
        """Optimize Twitter image URL for best quality."""
        if 'pbs.twimg.com/media/' in url:
            url = url.split('?')[0]  # Remove existing parameters
            url += "?format=jpg&name=orig"  # Add parameters for best quality
        elif 'pbs.twimg.com/profile_images/' in url:
            url = re.sub(r'_(normal|bigger|mini)(\..+)$', r'\2', url)  # Remove size suffix
        return url
