```matlab
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% CE2: Robust Control of an Electromechanical System
%
%% 2.2 Model-Based H2 Controller Design
% H2 state feedback controller design using LMI formulation with
% Schur complement and bounded real lemma
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
clc
clear all
close all

% Load system data
load('data3.mat')
G3 = bj(data3, [5, 5, 5, 5, 1]);

% Convert to continuous-time
G3_c = d2c(G3);
[A, B, C, D] = ssdata(G3_c); % Get state-space matrices
n = size(A,1); % Number of states
m = size(B,2); % Number of inputs
p = size(C,1); % Number of outputs

% Define YALMIP variables
X = sdpvar(n,n,'symmetric'); % Lyapunov matrix
Y = sdpvar(m,n,'full');      % Y = K*X
Z = sdpvar(p,p,'symmetric'); % For trace minimization

% Define LMI constraints using Schur complement and bounded real lemma
% Main stability LMI: A*X + X*A' - B*Y - Y'*B' + B*B' <= 0
lmi1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -1e-6*eye(n)];

% Positive definiteness constraint
lmi2 = [X >= 1e-6*eye(n)];

% Schur complement for trace minimization: [Z C*X; X*C' X] >= 0
lmi3 = [[Z C*X; X*C' X] >= 0];

% Combine all LMIs
LMIs = [lmi1, lmi2, lmi3];

% Objective: Minimize trace(Z) which bounds the H2 norm squared
objective = trace(Z);

% Solve the LMI problem
options = sdpsettings('solver','sedumi','verbose',0);
diag = optimize(LMIs, objective, options);

% Check solution
if diag.problem == 0
    % Extract solution
    X_opt = value(X);
    Y_opt = value(Y);

    % Compute controller gain: K = Y*X^-1
    K = Y_opt / X_opt;

    % Compute closed-loop system
    A_cl = A - B*K;
    sys_cl = ss(A_cl, B, C, zeros(size(D)));

    % Compute H2 norm using Lyapunov equation
    P = lyap(A_cl, B*B');
    h2_norm = sqrt(trace(C*P*C'));

    disp('Controller design successful');
    disp(['Achieved H2 norm: ' num2str(h2_norm)]);

    % Plot step response
    figure;
    step(sys_cl);
    title('Step Response - H2 Controller');

    % Compare with LQR
    Q_lqr = C'*C + 1e-3*eye(n);
    R_lqr = 1;
    K_lqr = lqr(A,B,Q_lqr,R_lqr);
    sys_cl_lqr = ss(A-B*K_lqr,B,C,D);

    figure;
    step(sys_cl_lqr);
    title('Step Response - LQR Controller');

    % Compare step responses
    figure;
    step(sys_cl, 'b', sys_cl_lqr, 'r--');
    legend('H2 Controller', 'LQR Controller');
    title('Step Response Comparison');

else
    error('LMI problem could not be solved');
end
