Y = sdpvar(size(B,2), size(A,1), 'full');
Z1 = sdpvar(size(C,1), size(C,1), 'symmetric');  % For output term
Z2 = sdpvar(size(B,2), size(B,2), 'symmetric');  % For control term

% Bounded Real Lemma for stability
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -1e-6*eye(size(A))];

