%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using YALMIP LMI Formulation
%
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms from disturbance to output and control input.
% The implementation uses the Schur Complement Lemma and Bounded Real Lemma
% to handle nonlinearities and represent the problem as LMIs.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

clc
clear all
close all

%% Load system data and create state-space model
load('data3.mat');
G3 = bj(data3, [5, 5, 5, 5, 1]);
G3_c = d2c(G3);  % Convert to continuous-time
[A, B, C, D] = ssdata(G3_c);

%% Define problem dimensions
n = size(A, 1);  % Number of states
m = size(B, 2);  % Number of inputs
p = size(C, 1);  % Number of outputs

%% LMI Formulation using YALMIP
% Define decision variables
X = sdpvar(n, n, 'symmetric');  % Lyapunov matrix
Y = sdpvar(m, n, 'full');       % Y = K*X
Z1 = sdpvar(p, p, 'symmetric'); % For output term
Z2 = sdpvar(m, m, 'symmetric'); % For control term

% Small constant for strict inequalities
epsilon = 1e-6;

% LMI constraints using Bounded Real Lemma and Schur Complement
constraints = [
    A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*eye(n),  % Stability
    X >= epsilon*eye(n),                                 % Positive definite
    [Z1, C*X; X*C', X] >= 0,                            % Output term
    [Z2, Y; Y', X] >= 0                                 % Control term
];

% Objective: Minimize trace(Z1) + trace(Z2)
objective = trace(Z1) + trace(Z2);

% Solver settings
options = sdpsettings('solver', 'sedumi', 'verbose', 1);

% Solve the optimization problem
diagnostics = optimize(constraints, objective, options);

%% Extract solution and compute controller
X_opt = value(X);
Y_opt = value(Y);
K = Y_opt / X_opt;  % Controller gain: K = Y*X^-1

%% Compute achieved H2 norm
A_cl = A - B*K;
P = lyap(A_cl, B*B');
h2_norm = sqrt(trace(C*P*C') + trace(K*P*K'));

%% Plot step response of H2 controller
sys_cl_h2 = ss(A_cl, B, C, D);
figure;
step(sys_cl_h2);
title('Step Response - H2 Controller');
grid on;

%% Compare with LQR controller
Q = C'*C + 1e-3*eye(n);
R = eye(m);
[K_lqr, ~, ~] = lqr(A, B, Q, R);
sys_cl_lqr = ss(A-B*K_lqr, B, C, D);

figure;
step(sys_cl_h2, 'b', sys_cl_lqr, 'r--');
legend('H2 Controller', 'LQR Controller');
title('Step Response Comparison');
grid on;

%% Display performance metrics
fprintf('H2 Controller Performance:\n');
fprintf('-------------------------\n');
fprintf('H2 Norm: %.4f\n', h2_norm);
fprintf('Control Effort (||K||_F): %.4f\n\n', norm(K, 'fro'));

fprintf('LQR Controller Performance:\n');
fprintf('-------------------------\n');
fprintf('H2 Norm: %.4f\n', norm(h2norm(sys_cl_lqr)));
fprintf('Control Effort (||K||_F): %.4f\n', norm(K_lqr, 'fro'));
