    /**
     * Compute the Linear Approximation Table for a 3-bit S-box
     */
    public static int[][] computeLAT(int[] sbox) {
        int[][] lat = new int[8][8];

        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                int count = 0;

                for (int x = 0; x < 8; x++) {
                    // Get binary representation of input x
                    int x0 = (x >> 2) & 1;
                    int x1 = (x >> 1) & 1;
                    int x2 = x & 1;

                    // Get S-box output for input x
                    int fx = sbox[x];
                    int fx0 = (fx >> 2) & 1;
                    int fx1 = (fx >> 1) & 1;
                    int fx2 = fx & 1;

                    // Get binary representation of masks a and b
                    int a0 = (a >> 2) & 1;
                    int a1 = (a >> 1) & 1;
                    int a2 = a & 1;
                    int b0 = (b >> 2) & 1;
                    int b1 = (b >> 1) & 1;
                    int b2 = b & 1;

                    // Compute a·x and b·S(x)
                    int aDotX = (a0 & x0) ^ (a1 & x1) ^ (a2 & x2);
                    int bDotFx = (b0 & fx0) ^ (b1 & fx1) ^ (b2 & fx2);

                    if (aDotX == bDotFx) {
                        count++;
                    }
                }

                lat[a][b] = count - 4; // Normalization
            }
        }

        return lat;
    }

