            // Get binary representation of input x (MSB first)
            int x0 = (x >> 2) & 1;  // Most significant bit
            int x1 = (x >> 1) & 1;
            int x2 = x & 1;         // Least significant bit

            // Get S-box output for input x
            int fx = sbox[x];

            // Get binary representation of S-box output (MSB first)
            int fx0 = (fx >> 2) & 1;
            int fx1 = (fx >> 1) & 1;
            int fx2 = fx & 1;

            // Get binary representation of masks
            int a0 = (a >> 2) & 1;
            int a1 = (a >> 1) & 1;
            int a2 = a & 1;

            int b0 = (b >> 2) & 1;
            int b1 = (b >> 1) & 1;
            int b2 = b & 1;

            // Compute a·x = Σ (a_i & x_i) mod 2
            int a_dot_x = (a0 & x0) ^ (a1 & x1) ^ (a2 & x2);

            // Compute b·S(x) = Σ (b_i & S(x)_i) mod 2
            int b_dot_fx = (b0 & fx0) ^ (b1 & fx1) ^ (b2 & fx2);

            if(a_dot_x == b_dot_fx) {
                count++;
            }
        }

        return count;
