        controls.enableDamping = true;
        controls.dampingFactor = 0.25;

        // Position camera
        camera.position.z = 5;

        // Create parametric geometry for the function
        function createParametricGeometry() {
            // Hyperbolic paraboloid function (can be changed to any z = f(x,y))
            const func = (u, v, target) => {
                // Map u,v ∈ [0,1] to x,y ∈ [-1,1]
                const x = -1 + u * 2;
                const y = -1 + v * 2;
                const z = x * x - y * y;  // Hyperbolic paraboloid

                target.set(x, y, z * 0.5);  // Scale z for better visualization
            };

            // Create geometry with 20 segments in each direction
            const geometry = new THREE.ParametricGeometry(func, 20, 20);

            // Create material
            const material = new THREE.MeshPhongMaterial({
                color: 0x3399ff,
                side: THREE.DoubleSide,
                wireframe: false,
                transparent: true,
                opacity: 0.8
            });

            // Create mesh
            const mesh = new THREE.Mesh(geometry, material);
            scene.add(mesh);

            // Add wireframe
            const wireframe = new THREE.LineSegments(
                new THREE.WireframeGeometry(geometry),
                new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.3 })
            );
            mesh.add(wireframe);
        }

        // Add reference plane (grid)
        function addReferencePlane() {
            const planeGeometry = new THREE.PlaneGeometry(4, 4);
            const planeMaterial = new THREE.MeshBasicMaterial({
                color: 0xcccccc,
                side: THREE.DoubleSide,
                transparent: true,
