    @staticmethod
    def get_total_of_charges_table() -> float:
        """Simulate Redux selector for getting total charges"""
        return 0.0

def outstanding_transactions_handler_simplified() -> StepResponse:
    """
    Simplified version that reduces deep copies and maintains edge case handling.

    Key improvements:
    1. No deep copies - creates new objects only when needed
    2. Maintains robust edge case handling for totalOfChargesTable = 0
    3. Single pass processing with minimal branching
    4. Clear validation of credit objects

    Returns:
        StepResponse: Result of the operation
    """
    try:
        # Get and validate data
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        # Edge case handling
        if not isinstance(credit_table_lines, list):
            credit_table_lines = []

        if not isinstance(total_charges, (int, float)) or total_charges < 0:
            total_charges = 0.0

        if not credit_table_lines or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        # Process credits
        remaining_balance = float(total_charges)
        updated_credits = []
        has_updates = False

        for credit in credit_table_lines:
            # Skip invalid credits
            if not hasattr(credit, 'txn_id') or not hasattr(credit, 'open_balance'):
                updated_credits.append(credit)
                continue

            # Skip if no linked payment to process
            if not credit.linked_payment_amount.strip():
                updated_credits.append(credit)
                continue

            # Determine new amount
            if remaining_balance >= credit.open_balance:
                new_amount = str(credit.open_balance)
                remaining_balance -= credit.open_balance
            elif remaining_balance > 0:
                new_amount = str(remaining_balance)
                remaining_balance = 0
            else:
                new_amount = ""

            # Only create new object if amount changed
            if credit.linked_payment_amount != new_amount:
                has_updates = True
                updated_credit = CreditChargesPayment(
                    txn_id=credit.txn_id,
                    open_balance=credit.open_balance,
                    linked_payment_amount=new_amount
                )
                updated_credits.append(updated_credit)
            else:
                updated_credits.append(credit)

        # Dispatch update if changes occurred
        if has_updates:
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        print(f"Error processing transactions: {e}")
        return StepResponse(result=ResultType.FAILURE)


# Example usage
if __name__ == "__main__":
    # Test with totalOfChargesTable = 0 edge case
    class EdgeCaseSelectors(PaymentTableSelectors):
        @staticmethod
        def get_credits() -> List[CreditChargesPayment]:
            return [
                CreditChargesPayment(txn_id="1", open_balance=100.0, linked_payment_amount="50"),
            ]

        @staticmethod
        def get_total_of_charges_table() -> float:
            return 0.0

    PaymentTableSelectors = EdgeCaseSelectors

    print("Testing totalOfChargesTable = 0 edge case:")
    result = outstanding_transactions_handler_simplified()
    print(f"Result: {result.result.value}")
