```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

vector<ll> dijkstra(int n, const vector<vector<pair<int, int>>>& adj, int start) {
    vector<ll> dist(n + 1, INF);
    dist[start] = 0;
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            ll newDist = d + w;
            if (newDist < dist[v]) {
                dist[v] = newDist;
                pq.push({newDist, v});
            }
        }
    }
    return dist;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    vector<ll> dist1 = dijkstra(n, adj, 1);
    vector<ll> distN = dijkstra(n, adj, n);

    vector<pair<ll, ll>> nodes;
    for (int i = 1; i <= n; i++) {
        nodes.push_back({dist1[i], distN[i]});
    }
    sort(nodes.begin(), nodes.end());

    vector<ll> prefix_min(n);
    prefix_min[0] = nodes[0].second;
    for (int i = 1; i < n; i++) {
        prefix_min[i] = min(prefix_min[i-1], nodes[i].second);
    }

    for (int day = 0; day < k; day++) {
        ll a, b;
        cin >> a >> b;

        ll lo = 0, hi = INF;
        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            bool possible = false;

            ll maxDist1 = (a > 0) ? mid / a : INF;
            auto it = upper_bound(nodes.begin(), nodes.end(), make_pair(maxDist1, INF));
            int pos = it - nodes.begin();

            if (pos > 0) {
                ll maxDist2 = (b > 0) ? mid / b : INF;
                if (prefix_min[pos-1] <= maxDist2) {
                    possible = true;
                }
            }

            if (possible) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        cout << lo << "\n";
    }

    return 0;
}
```

**Key Optimizations:**

1. **Prefix Minimum Array**: Replaced linear scan with O(1) lookup using precomputed prefix minimums of `distN` values.
2. **Efficient Binary Search**: The check phase now uses `upper_bound` and prefix minimums for O(log n) complexity per check.
3. **Edge Case Handling**:
   - Properly handles division by zero with `(a > 0)` and `(b > 0)` checks
   - Uses `INF = 1e18` to accommodate maximum constraints
   - Works correctly with minimal inputs (n=2, m=1, k=1)
4. **Complexity**:
   - Dijkstra: O((n + m) log n)
   - Sorting: O(n log n)
   - Per query: O(log n log INF)
   - Overall: O((n + m) log n + k log n log INF)

**Algorithm**:
1. Compute shortest paths from both endpoints
2. Sort nodes by distance from node 1
3. Precompute prefix minimums of distances from node n
4. For each query, binary search the minimal maximum travel time:
   - Use `upper_bound` to find range of nodes with `dist1 ≤ T/a`
   - Check if any node in range has `distN ≤ T/b` via prefix minimum
5. Output the minimal maximum time (which equals the minimal waiting time)

