#include <functional>
#include <unordered_map>

template<typename T>
class MatrixMinorCalculator {
private:
    std::vector<std::vector<T>> data;
    size_t n;

    // Pre-allocated buffers for performance
    mutable std::vector<std::vector<T>> minor_buffer;
    mutable std::vector<T> temp_row;

public:
    MatrixMinorCalculator(const std::vector<std::vector<T>>& mat) 
        : data(mat), n(mat.size()) {
        validateMatrix();
        // Pre-allocate buffers
        if (n > 1) {
            minor_buffer.resize(n-1, std::vector<T>(n-1));
            temp_row.resize(n-1);
        }
    }

    // Optimized minor determinant calculation
    T minorDeterminant(size_t row, size_t col, bool useOptimized = true) const {
        // Validate indices using STL algorithms
        if (row >= n || col >= n) {
            throw std::out_of_range("Indices out of bounds");
        }

        // Edge cases
        if (n == 1) return static_cast<T>(1);
        if (n == 2) return data[1-row][1-col];

        // For small matrices (n ≤ 10), use optimized recursive approach
        if (useOptimized && n <= 10) {
            return optimizedRecursiveMinor(row, col);
        }

        // For larger matrices, use LU decomposition
        return luMinorDeterminant(row, col);
    }

private:
    void validateMatrix() const {
        if (n == 0) throw std::invalid_argument("Matrix cannot be empty");

        // Use STL algorithm to check squareness
        bool is_square = std::all_of(data.begin(), data.end(),
            [this](const auto& row) { return row.size() == n; });

        if (!is_square) {
            throw std::invalid_argument("Matrix must be square");
        }
    }

    T optimizedRecursiveMinor(size_t row, size_t col) const {
        // Create minor matrix using pre-allocated buffer
        size_t minor_i = 0;
        for (size_t i = 0; i < n; ++i) {
            if (i == row) continue;

            const auto& src_row = data[i];
            auto& dst_row = minor_buffer[minor_i];

            size_t minor_j = 0;
            for (size_t j = 0; j < n; ++j) {
                if (j == col) continue;
                dst_row[minor_j++] = src_row[j];
            }
            ++minor_i;
        }

        return optimizedDeterminantRecursive(minor_buffer);
    }

    T optimizedDeterminantRecursive(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();

        // Optimized base cases
        if (m == 1) return mat[0][0];
        if (m == 2) return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
        if (m == 3) {
            // Sarrus' rule for 3x3
            return mat[0][0] * (mat[1][1] * mat[2][2] - mat[1][2] * mat[2][1])
                 - mat[0][1] * (mat[1][0] * mat[2][2] - mat[1][2] * mat[2][0])
                 + mat[0][2] * (mat[1][0] * mat[2][1] - mat[1][1] * mat[2][0]);
        }

        // Find row with most zeros for efficiency
        size_t best_row = 0;
        size_t max_zeros = 0;
        for (size_t i = 0; i < m; ++i) {
            size_t zeros = std::count_if(mat[i].begin(), mat[i].end(), 
                [](T val) { return std::abs(val) < 1e-12; });
            if (zeros > max_zeros) {
                max_zeros = zeros;
                best_row = i;
            }
        }

        T det = 0;

        // Create temporary buffer for minor matrix
        std::vector<std::vector<T>> minor_mat(m-1, std::vector<T>(m-1));

        // Expand along best_row
        for (size_t j = 0; j < m; ++j) {
            if (std::abs(mat[best_row][j]) < 1e-12) continue;

            // Build minor matrix
            size_t minor_i = 0;
            for (size_t i = 0; i < m; ++i) {
                if (i == best_row) continue;

                size_t minor_j = 0;
                for (size_t k = 0; k < m; ++k) {
                    if (k == j) continue;
                    minor_mat[minor_i][minor_j++] = mat[i][k];
                }
                ++minor_i;
            }

            // Compute cofactor
            T sign = ((best_row + j) % 2 == 0) ? 1 : -1;
            det += sign * mat[best_row][j] * optimizedDeterminantRecursive(minor_mat);
        }

        return det;
    }

    T luMinorDeterminant(size_t row, size_t col) const {
        // Create minor matrix
        std::vector<std::vector<T>> minor_mat(n-1, std::vector<T>(n-1));

        size_t minor_i = 0;
        for (size_t i = 0; i < n; ++i) {
            if (i == row) continue;

            size_t minor_j = 0;
            for (size_t j = 0; j < n; ++j) {
                if (j == col) continue;
                minor_mat[minor_i][minor_j++] = data[i][j];
            }
            ++minor_i;
        }

        return luDeterminant(minor_mat);
    }

    T luDeterminant(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();

        // Initialize LU matrices
        std::vector<std::vector<T>> LU = mat;
        std::vector<size_t> P(m);
        std::iota(P.begin(), P.end(), 0); // Initialize permutation vector

        T det = 1;

        // LU decomposition with partial pivoting
        for (size_t k = 0; k < m; ++k) {
            // Partial pivoting
            size_t max_row = k;
            T max_val = std::abs(LU[k][k]);

            for (size_t i = k + 1; i < m; ++i) {
                T val = std::abs(LU[i][k]);
                if (val > max_val) {
                    max_val = val;
                    max_row = i;
                }
            }

            if (max_row != k) {
                // Swap rows in LU
                std::swap(LU[k], LU[max_row]);
                // Update permutation
                std::swap(P[k], P[max_row]);
                det = -det; // Swap changes determinant sign
            }

            if (std::abs(LU[k][k]) < 1e-12) {
                return 0; // Singular matrix
            }

            // Gaussian elimination
            for (size_t i = k + 1; i < m; ++i) {
                LU[i][k] /= LU[k][k];
                for (size_t j = k + 1; j < m; ++j) {
                    LU[i][j] -= LU[i][k] * LU[k][j];
                }
            }
        }

        // Compute determinant as product of diagonal elements
        for (size_t i = 0; i < m; ++i) {
            det *= LU[i][i];
        }

        return det;
    }
};

