%% 1. Wiener Filter Implementation for Frequency Domain Degradation
function restored = wiener_fourier_restoration(y, noise_var, signal_var)
    % WIENER_FOURIER_RESTORATION Wiener filter adapted for frequency interference
    % 
    % Inputs:
    %   y - Degraded image
    %   noise_var - Estimated noise variance
    %   signal_var - Estimated signal variance
    %
    % Output:
    %   restored - Restored image

    y_double = im2double(y);
    [M,N] = size(y_double);

    % Compute Fourier Transform
    Y = fft2(y_double);
    Y_shifted = fftshift(Y);

    % Create frequency mask for corrupted regions
    magnitude = abs(Y_shifted);
    median_mag = median(magnitude(:));
    threshold = 10 * median_mag;
    [corr_rows, corr_cols] = find(magnitude > threshold);

    % Estimate degradation function
    H_est = ones(M,N);
    for i = 1:length(corr_rows)
        r = corr_rows(i);
        c = corr_cols(i);
        H_est(r,c) = 0.1;  % Reduce gain at corrupted frequencies

        % Handle symmetric frequency
        sym_r = M - r + 1;
        sym_c = N - c + 1;
        H_est(sym_r,sym_c) = 0.1;
    end

    % Wiener filter in frequency domain
    H_conj = conj(H_est);
    H_mag_sq = abs(H_est).^2;
    NSR = noise_var / (signal_var + eps);
    W = H_conj ./ (H_mag_sq + NSR);

    % Apply filter
    F_hat_shifted = Y_shifted .* W;
    F_hat = ifftshift(F_hat_shifted);
    restored = real(ifft2(F_hat));
    restored = max(0, min(1, restored));
end

%% 2. Lucy-Richardson Deconvolution for Frequency Artifacts
function restored = lr_fourier_restoration(y, psf, iterations, damping)
    % LR_FOURIER_RESTORATION Lucy-Richardson for Fourier domain artifacts
    %
    % Inputs:
    %   y - Degraded image
    %   psf - Point Spread Function
    %   iterations - Number of iterations
    %   damping - Damping factor (0-1)
    %
    % Output:
    %   restored - Restored image

    if nargin < 4
        damping = 0.1;
    end

    y_double = im2double(y);

    % Default PSF for frequency interference
    if nargin < 2 || isempty(psf)
        psf_size = 5;
        psf = zeros(psf_size);
        psf(ceil(psf_size/2), ceil(psf_size/2)) = 1;
        psf(1,1) = 0.1;
        psf(end,end) = 0.1;
        psf = psf / sum(psf(:));
    end

    % Convert PSF to OTF
    otf = psf2otf(psf, size(y_double));

    % Initialize estimate
    est = y_double;

    for iter = 1:iterations
        % Apply degradation model
        est_fft = fft2(est);
        blurred_est = real(ifft2(est_fft .* otf));

        % Compute correction
        ratio = y_double ./ (blurred_est + eps);
        correction = real(ifft2(fft2(ratio) .* conj(otf)));

        % Update estimate with damping
        est = est .* (1-damping) + est .* correction * damping;
        est = max(0, est);
    end

    restored = max(0, min(1, est));
end

