#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <random>
#include <cmath>
#include <stdexcept>
#include <algorithm>
#include <chrono>
#include <mutex>
#include <atomic>
#include <string>

// ============================================================================
// NEURON CLASS WITH DYNAMIC PARAMETER MODIFICATION
// ============================================================================

class IzhikevichNeuron {
private:
    // Neuron identification and parameters
    size_t id_;
    double a_, b_, c_, d_, v_rest_;

    // State variables
    double v_, u_, I_;

    // Spike tracking
    bool has_spiked_;
    std::vector<double> spike_times_;
    double last_spike_time_;

    // Connectivity
    std::unordered_map<size_t, double> input_weights_;
    std::unordered_map<size_t, double> output_weights_;

    // STDP parameters
    double stdp_learning_rate_;
    double stdp_tau_plus_;
    double stdp_tau_minus_;

    // Thread safety
    mutable std::mutex neuron_mutex_;

public:
    IzhikevichNeuron(size_t id, double a = 0.02, double b = 0.2, 
                    double c = -65.0, double d = 8.0, double v_rest = -70.0)
        : id_(id), a_(a), b_(b), c_(c), d_(d), v_rest_(v_rest),
          v_(v_rest), u_(b * v_rest), I_(0.0),
          has_spiked_(false), last_spike_time_(-1000.0),
          stdp_learning_rate_(0.01), stdp_tau_plus_(20.0), stdp_tau_minus_(20.0) {}

    // Dynamic parameter modification methods
    void update_parameters(double a = NAN, double b = NAN, 
                          double c = NAN, double d = NAN,
                          double v_rest = NAN) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        if (!std::isnan(a)) a_ = a;
        if (!std::isnan(b)) b_ = b;
        if (!std::isnan(c)) c_ = c;
        if (!std::isnan(d)) d_ = d;
        if (!std::isnan(v_rest)) v_rest_ = v_rest;
    }

    // Connection management
    bool connect_to(size_t target_id, double weight = 0.5) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        if (target_id == id_) return false;
        return output_weights_.emplace(target_id, weight).second;
    }

    bool add_input(size_t source_id, double weight) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        if (source_id == id_) return false;
        return input_weights_.emplace(source_id, weight).second;
    }

    // Disconnection methods
    bool disconnect_from(size_t target_id) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return output_weights_.erase(target_id) > 0;
    }

    bool remove_input(size_t source_id) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);
        return input_weights_.erase(source_id) > 0;
    }

    // Neuron dynamics
    bool step(double dt, double current_time, 
             const std::unordered_map<size_t, double>& spiking_neurons) {
        std::lock_guard<std::mutex> lock(neuron_mutex_);

        // Calculate input current
        I_ = 0.0;
        for (const auto& [id, strength] : spiking_neurons) {
            auto it = input_weights_.find(id);
            if (it != input_weights_.end()) {
                I_ += it->second * strength;
            }
        }

        // Izhikevich equations
        double dv = (0.04 * v_ * v_ + 5 * v_ + 140 - u_ + I_) * dt;
        double du = (a_ * (b_ * v_ - u_)) * dt;

        v_ += dv;
        u_ += du;

        // Check for spike
        has_spiked_ = (v_ >= 30.0);
        if (has_spiked_) {
            spike_times_.push_back(current_time);
            last_spike_time_ = current_time;
            v_ = c_;
            u_ += d_;
        }

        return has_spiked_;
    }
};

// ============================================================================
// NEURAL NETWORK CLASS
// ============================================================================

class NeuralNetwork {
private:
    std::unordered_map<size_t, std::shared_ptr<IzhikevichNeuron>> neurons_;
    double current_time_;
    size_t next_id_;
    std::mt19937 rng_;

public:
    NeuralNetwork() : current_time_(0.0), next_id_(0), 
                     rng_(std::random_device{}()) {}

    void add_neuron(std::shared_ptr<IzhikevichNeuron> neuron) {
        neurons_[neuron->get_id()] = neuron;
        next_id_ = std::max(next_id_, neuron->get_id() + 1);
    }

    void create_random_connections(double probability = 0.1) {
        std::vector<size_t> ids;
        for (const auto& [id, _] : neurons_) ids.push_back(id);

        std::uniform_real_distribution<double> dist(0.0, 1.0);

        for (size_t src : ids) {
            for (size_t tgt : ids) {
                if (src != tgt && dist(rng_) < probability) {
                    double weight = 0.1 + 0.8 * dist(rng_);
                    if (neurons_[src]->connect_to(tgt, weight)) {
                        neurons_[tgt]->add_input(src, weight);
                    }
                }
            }
        }
    }

    void step(double dt) {
        // Collect spiking neurons
        std::unordered_map<size_t, double> spiking;
        for (const auto& [id, neuron] : neurons_) {
            if (neuron->has_spiked()) {
                spiking[id] = 1.0;
            }
        }

        // Update all neurons
        for (auto& [_, neuron] : neurons_) {
            neuron->step(dt, current_time_, spiking);
        }

        current_time_ += dt;
    }
};

// ============================================================================
// EXAMPLE USAGE
// ============================================================================

int main() {
    // Create network
    NeuralNetwork network;

    // Add different neuron types
    for (size_t i = 0; i < 50; ++i) {  // Sensory neurons
        auto neuron = std::make_shared<IzhikevichNeuron>(i, 0.02, 0.2, -65.0, 8.0);
        network.add_neuron(neuron);
    }

    for (size_t i = 50; i < 70; ++i) {  // Interneurons
        auto neuron = std::make_shared<IzhikevichNeuron>(i, 0.1, 0.2, -65.0, 2.0);
        network.add_neuron(neuron);
    }

    for (size_t i = 70; i < 100; ++i) {  // Motor neurons
        auto neuron = std::make_shared<IzhikevichNeuron>(i, 0.02, 0.2, -65.0, 8.0);
        network.add_neuron(neuron);
    }

    // Create random connections
    network.create_random_connections(0.1);

    // Simulate for 1000 time steps
    for (int step = 0; step < 1000; ++step) {
        network.step(0.5);  // 0.5ms time step

        // Example: Modify neuron parameters during simulation
        if (step == 500) {
            for (size_t i = 0; i < 50; ++i) {
                // Increase excitability of sensory neurons
                network.get_neuron(i)->update_parameters(NAN, NAN, NAN, 10.0);
            }
        }
    }

    return 0;
}
