class BodyMetricsPage extends StatefulWidget {
  final String uid;
  final String? profileImageUrl;

  BodyMetricsPage({required this.uid, this.profileImageUrl});

  @override
  _BodyMetricsPageState createState() => _BodyMetricsPageState();
