class _BodyMetricsPageState extends State<BodyMetricsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightController = TextEditingController();
  final _heightController = TextEditingController();
  final List<String> _bodyTypes = ['Ectomorph', 'Mesomorph', 'Endomorph', 'Other'];
  String? _selectedBodyType;
  bool _isLoading = false;
  String _errorMessage = '';

  final FirebaseFirestore _firestore = FirebaseFirestore.instance;

  // Validate weight input
  bool _validateWeight(String value) {
    final weight = double.tryParse(value);
    return weight != null && weight > 0 && weight <= 300;
  }

  // Validate height input
  bool _validateHeight(String value) {
    final height = double.tryParse(value);
    return height != null && height > 0 && height <= 250;
  }

  Future<void> _saveBodyMetrics() async {
    if (!_formKey.currentState!.validate()) return;
    if (_selectedBodyType == null) {
      setState(() { _errorMessage = 'Please select a body type'; });
      return;
    }

    setState(() { _isLoading = true; _errorMessage = ''; });

    try {
      // Calculate BMI
      final heightM = double.parse(_heightController.text) / 100;
      final bmi = double.parse(_weightController.text) / (heightM * heightM);

      // Save all data to Firestore
      await _firestore.collection('users').doc(widget.uid).set({
        'weight': double.parse(_weightController.text),
        'height': double.parse(_heightController.text),
        'body_type': _selectedBodyType,
        'bmi': bmi.toStringAsFixed(1),
        'profile_completed': true,
        'updated_at': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      // Navigate to profile page
      Navigator.pushAndRemoveUntil(
        context,
        MaterialPageRoute(builder: (context) => ProfilePage(uid: widget.uid)),
        (route) => false,
      );
    } catch (e) {
      setState(() { _errorMessage = 'Error saving data: $e'; });
    } finally {
      setState(() { _isLoading = false; });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Body Metrics')),
      body: Padding(
        padding: EdgeInsets.all(20),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _weightController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(labelText: 'Weight (kg)'),
                validator: (value) => _validateWeight(value ?? '') 
                  ? null : 'Enter valid weight (0-300 kg)',
              ),
              TextFormField(
                controller: _heightController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(labelText: 'Height (cm)'),
                validator: (value) => _validateHeight(value ?? '') 
                  ? null : 'Enter valid height (0-250 cm)',
              ),
              DropdownButtonFormField<String>(
                value: _selectedBodyType,
                items: _bodyTypes.map((type) => 
                  DropdownMenuItem(value: type, child: Text(type))
                ).toList(),
                onChanged: (value) => setState(() => _selectedBodyType = value),
                decoration: InputDecoration(labelText: 'Body Type'),
              ),
              ElevatedButton(
                onPressed: _isLoading ? null : _saveBodyMetrics,
                child: _isLoading 
                  ? CircularProgressIndicator() 
                  : Text('Save Metrics'),
              ),
              if (_errorMessage.isNotEmpty)
                Text(_errorMessage, style: TextStyle(color: Colors.red)),
            ],
          ),
        ),
      ),
    );
  }
}

