namespace NanoCAD.TableOperations
{
    public static class DirectTableEmbedder
    {
        public static bool EmbedPrimitivesDirectly(
            List<EntityGeometry> entities,
            McTable table,
            int rowIndex,
            int columnIndex)
        {
            // Validate inputs
            if (!ValidateInputs(entities, table, rowIndex, columnIndex))
                return false;

            try
            {
                // Create compound geometry
                using (McCompound compound = new McCompound())
                {
                    compound.Name = $"Embedded_{DateTime.Now:yyyyMMdd_HHmmss}";

                    // Add entities
                    foreach (var entity in entities)
                    {
                        if (entity != null)
                        {
                            EntityGeometry cloned = entity.Clone() as EntityGeometry;
                            if (cloned != null)
                                compound.Entities.Add(cloned);
                        }
                    }

                    if (compound.Entities.Count == 0)
                    {
                        Logger.AddMessage("No valid geometry to embed");
                        return false;
                    }

                    // Attempt direct embedding first
                    if (TryDirectEmbedding(table, rowIndex, columnIndex, compound))
                        return true;

                    // Fallback to image embedding
                    if (TryImageEmbedding(compound, table, rowIndex, columnIndex))
                        return true;

                    // Final fallback to block reference
                    return CreateBlockReference(compound, table, rowIndex, columnIndex);
                }
            }
            catch (Exception ex)
            {
                Logger.AddMessage($"Embedding failed: {ex.Message}");
                return false;
            }
        }

        private static bool ValidateInputs(
            List<EntityGeometry> entities,
            McTable table,
            int rowIndex,
            int columnIndex)
        {
            if (entities == null || entities.Count == 0)
            {
                Logger.AddMessage("No entities provided");
                return false;
            }

            if (table == null)
            {
                Logger.AddMessage("Table is null");
                return false;
            }

            if (rowIndex < 0 || rowIndex >= table.RowsCount)
            {
                Logger.AddMessage($"Invalid row index: {rowIndex}");
                return false;
            }

            if (columnIndex < 0 || columnIndex >= table.ColumnsCount)
            {
                Logger.AddMessage($"Invalid column index: {columnIndex}");
                return false;
            }

            return true;
        }

        private static bool TryDirectEmbedding(
            McTable table,
            int rowIndex,
            int columnIndex,
            McCompound compound)
        {
            try
            {
                // Try direct embedding methods
                table.SetCellContent(rowIndex, columnIndex, compound);
                Logger.AddMessage($"Successfully embedded geometry directly into cell [{rowIndex},{columnIndex}]");
                return true;
            }
            catch
            {
                Logger.AddMessage("Direct geometry embedding not supported by this API version");
                return false;
            }
        }

        private static bool TryImageEmbedding(
            McCompound compound,
            McTable table,
            int rowIndex,
            int columnIndex)
        {
