```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

public static class TableGeometryEmbedder
{
    public static bool EmbedPrimitivesToTableCell(
        List<EntityGeometry> entities,
        McTable table,
        int rowIndex,
        int columnIndex)
    {
        // 1. Validate input geometry
        if (entities == null || !entities.Any() || entities.All(e => e == null))
        {
            Logger.AddMessage("Error: No valid geometry entities provided");
            return false;
        }

        // 2. Validate table and indices
        if (table == null)
        {
            Logger.AddMessage("Error: Table reference is null");
            return false;
        }

        if (rowIndex < 0 || rowIndex >= table.RowsCount ||
            columnIndex < 0 || columnIndex >= table.ColumnsCount)
        {
            Logger.AddMessage("Error: Invalid row or column index");
            return false;
        }

        try
        {
            // 3. Create compound entity
            using (var compound = new McCompound())
            {
                compound.Name = $"Embedded_{DateTime.Now:yyyyMMdd_HHmmss}";

                // Add cloned entities
                foreach (var entity in entities.Where(e => e != null))
                {
                    var clone = entity.Clone() as EntityGeometry;
                    if (clone != null) compound.Entities.Add(clone);
                }

                if (!compound.Entities.Any())
                {
                    Logger.AddMessage("Error: No valid geometry could be cloned");
                    return false;
                }

                // 4. Direct embedding using confirmed McTable API methods
                table.SetCellContent(rowIndex, columnIndex, compound);
                Logger.AddMessage("Successfully embedded geometry into table cell");
                return true;
            }
        }
        catch (Exception ex)
        {
            Logger.AddMessage($"Embedding failed: {ex.Message}");
            return false;
        }
    }
}
