## Python Backend for AWS RDS MySQL Connection

```python
from flask import Flask, request, jsonify
from flask_cors import CORS
import mysql.connector
from mysql.connector import Error, IntegrityError
import os
from dotenv import load_dotenv
import hashlib
import re
from datetime import datetime
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Load environment variables
load_dotenv()

app = Flask(__name__)
CORS(app)

# Database connection function
def get_db_connection():
    """Connect to AWS RDS MySQL database"""
    try:
        connection = mysql.connector.connect(
            host=os.getenv('DB_HOST'),
            database=os.getenv('DB_NAME'),
            user=os.getenv('DB_USER'),
            password=os.getenv('DB_PASSWORD'),
            port=int(os.getenv('DB_PORT', 3306))
        )
        logger.info("Connected to AWS RDS MySQL")
        return connection
    except Error as e:
        logger.error(f"Database connection error: {e}")
        return None

def create_table():
    """Create students table if not exists"""
    connection = get_db_connection()
    if connection:
        try:
            cursor = connection.cursor()
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS students (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    name VARCHAR(100) NOT NULL,
                    email VARCHAR(100) UNIQUE NOT NULL,
                    phone VARCHAR(20) NOT NULL,
                    password_hash VARCHAR(255) NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            connection.commit()
            logger.info("Students table ready")
        except Error as e:
            logger.error(f"Error creating table: {e}")
        finally:
            cursor.close()
            connection.close()

def hash_password(password):
    """Hash password using SHA-256"""
    return hashlib.sha256(password.encode()).hexdigest()

@app.route('/register', methods=['POST'])
def register_student():
    """Handle form submission and insert into AWS RDS"""
    try:
        if not request.is_json:
            return jsonify({'success': False, 'message': 'Invalid content type'}), 400

        data = request.json

        # Validate required fields
        required_fields = ['name', 'email', 'phone', 'password']
        if not all(field in data for field in required_fields):
            return jsonify({'success': False, 'message': 'Missing required fields'}), 400

        # Prepare data
        name = data['name'].strip()
        email = data['email'].strip().lower()
        phone = data['phone'].strip()
        password_hash = hash_password(data['password'])

        # Connect to database
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed'}), 500

        cursor = connection.cursor()

        # Insert into MySQL
        insert_query = """
        INSERT INTO students (name, email, phone, password_hash)
        VALUES (%s, %s, %s, %s)
        """

        try:
            cursor.execute(insert_query, (name, email, phone, password_hash))
            connection.commit()
            student_id = cursor.lastrowid

            return jsonify({
                'success': True,
                'message': f'Student {name} registered!',
                'student_id': student_id
            }), 201

        except IntegrityError:
            return jsonify({'success': False, 'message': 'Email already exists'}), 409

        except Error as e:
            logger.error(f"Database error: {e}")
            return jsonify({'success': False, 'message': 'Database error'}), 500

        finally:
            cursor.close()
            connection.close()

    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        return jsonify({'success': False, 'message': 'Server error'}), 500

@app.route('/health', methods=['GET'])
def health_check():
    """Check database connectivity"""
    try:
        connection = get_db_connection()
        if connection:
            connection.close()
            return jsonify({'status': 'healthy', 'database': 'connected'})
        else:
            return jsonify({'status': 'unhealthy', 'database': 'disconnected'}), 503
    except Exception as e:
        return jsonify({'status': 'unhealthy', 'error': str(e)}), 503

if __name__ == '__main__':
    create_table()
    app.run(debug=True, host='0.0.0.0', port=5000)
```

## AWS RDS MySQL Setup Instructions

1. **Create RDS Instance**:
   - Go to AWS RDS console
   - Click "Create database"
   - Select MySQL engine
   - Choose "Free tier" template for development
   - Set DB instance identifier, master username, and password

2. **Configure Database**:
   - DB instance class: db.t3.micro
   - Storage: 20GB (General Purpose SSD)
   - Enable public access for development
   - Set initial database name: student_database

3. **Security Group Configuration**:
   - Navigate to RDS instance details
   - Click on VPC security group link
   - Edit inbound rules:
     - Type: MySQL/Aurora
     - Source: Your IP address (or 0.0.0.0/0 for development)
     - Port: 3306

4. **Connect to Database**:
   - Note the RDS endpoint from instance details
   - Create `.env` file:
     ```
     DB_HOST=your-rds-endpoint.rds.amazonaws.com
     DB_NAME=student_database
     DB_USER=your_username
     DB_PASSWORD=your_password
     DB_PORT=3306
     ```

5. **Run Application**:
   ```bash
   pip install flask flask-cors mysql-connector-python python-dotenv
   python app.py
   ```

6. **Test Registration**:
   - Open HTML form in browser
   - Submit form with valid data
   - Verify data appears in MySQL database

## Form-to-Database Connection Flow

1. HTML form submits data via JavaScript fetch to `/register` endpoint
2. Flask backend validates input and connects to AWS RDS
3. Backend inserts form data into MySQL students table
4. Response returned to frontend with success/error message

